using System.Globalization;
using System.Text;
using PostSharp.Models;

namespace PostSharp.Services;

/// <summary>Parses the common bash-style cURL options generated by Postman, browsers and PostSharp.</summary>
public static class CurlImportService
{
    private static readonly HashSet<string> IgnoredFlags = new(StringComparer.Ordinal)
    {
        "--compressed",
        "--location",
        "-L",
        "--silent",
        "-s",
        "--insecure",
        "-k",
        "--verbose",
        "-v",
        "--no-buffer",
        "-N",
        "--globoff",
        "-g",
        "--http1.1",
        "--http2",
        "--http2-prior-knowledge",
        "-4",
        "-6",
        "-q",
        "-S",
        "-f",
        "-i",
        "-l",
        "-O",
        "-J",
    };

    private static readonly HashSet<string> IgnoredValueOptions = new(StringComparer.Ordinal)
    {
        "--cert",
        "--key",
        "--pass",
        "--cacert",
        "--capath",
        "--proxy",
        "--proxy-user",
        "--socks5",
        "--socks5-hostname",
        "--resolve",
        "--connect-to",
        "--interface",
        "--retry",
        "--retry-delay",
        "--limit-rate",
        "--max-redirs",
        "--output",
        "-o",
        "--dump-header",
        "-D",
        "--cookie-jar",
        "-c",
        "--upload-file",
        "-T",
        "--request-target",
        "--write-out",
        "-w",
        "--connect-timeout",
        "-x",
    };

    public static CurlImportResult Parse(string command)
    {
        if (string.IsNullOrWhiteSpace(command))
        {
            throw new InvalidOperationException("cURL 命令为空，请粘贴以 curl 开头的命令。");
        }

        var arguments = Tokenize(command);
        var startIndex = FindCommandStart(arguments);
        if (startIndex < 0)
        {
            throw new InvalidOperationException(
                "没有找到 curl 命令，请粘贴以 curl 开头的 bash 命令。"
            );
        }

        var warnings = new WarningBag();
        var headers = new List<KeyValuePair<string, string>>();
        var formFields = new List<ImportedField>();
        var dataParts = new List<string>();
        var parameters = new List<ImportedField>();
        var url = string.Empty;
        var method = string.Empty;
        var uploadFilePath = string.Empty;
        var uploadFieldName = "file";
        var fileCount = 0;
        var getMode = false;
        var jsonMode = false;
        var timeoutSeconds = 0;

        for (var index = startIndex; index < arguments.Count; index++)
        {
            var argument = arguments[index];
            if (argument is "&" or ";" or "|")
            {
                continue;
            }

            if (argument == "--")
            {
                if (index + 1 < arguments.Count && string.IsNullOrEmpty(url))
                {
                    index++;
                    url = arguments[index];
                }

                continue;
            }

            if (argument.StartsWith("--", StringComparison.Ordinal))
            {
                var (option, inlineValue) = SplitLongOption(argument);
                switch (option)
                {
                    case "--url":
                        SetUrl(
                            ref url,
                            ReadValue(arguments, ref index, inlineValue, option, warnings),
                            warnings
                        );
                        break;
                    case "--request":
                        method = ReadValue(arguments, ref index, inlineValue, option, warnings)
                            .Trim()
                            .ToUpperInvariant();
                        break;
                    case "--header":
                        AddHeader(
                            headers,
                            ReadValue(arguments, ref index, inlineValue, option, warnings),
                            warnings
                        );
                        break;
                    case "--data":
                    case "--data-raw":
                    case "--data-binary":
                    case "--data-ascii":
                        dataParts.Add(
                            ReadDataValue(
                                ReadValue(arguments, ref index, inlineValue, option, warnings),
                                warnings
                            )
                        );
                        break;
                    case "--data-urlencode":
                        dataParts.Add(
                            ReadValue(arguments, ref index, inlineValue, option, warnings)
                        );
                        warnings.Add("--data-urlencode 已按原始文本导入，导入后请复核编码。");
                        break;
                    case "--form":
                        AddFormField(
                            ReadValue(arguments, ref index, inlineValue, option, warnings),
                            formFields,
                            warnings,
                            ref uploadFilePath,
                            ref uploadFieldName,
                            ref fileCount
                        );
                        break;
                    case "--form-string":
                        AddFormString(
                            ReadValue(arguments, ref index, inlineValue, option, warnings),
                            formFields,
                            warnings
                        );
                        break;
                    case "--user":
                        AddBasicAuth(
                            headers,
                            ReadValue(arguments, ref index, inlineValue, option, warnings),
                            warnings
                        );
                        break;
                    case "--user-agent":
                        AddHeader(
                            headers,
                            $"User-Agent: {ReadValue(arguments, ref index, inlineValue, option, warnings)}",
                            warnings
                        );
                        break;
                    case "--referer":
                        AddHeader(
                            headers,
                            $"Referer: {ReadValue(arguments, ref index, inlineValue, option, warnings)}",
                            warnings
                        );
                        break;
                    case "--cookie":
                        AddHeader(
                            headers,
                            $"Cookie: {ReadValue(arguments, ref index, inlineValue, option, warnings)}",
                            warnings
                        );
                        break;
                    case "--oauth2-bearer":
                        AddHeader(
                            headers,
                            $"Authorization: Bearer {ReadValue(arguments, ref index, inlineValue, option, warnings)}",
                            warnings
                        );
                        break;
                    case "--max-time":
                        timeoutSeconds = ParseTimeout(
                            ReadValue(arguments, ref index, inlineValue, option, warnings),
                            timeoutSeconds,
                            warnings
                        );
                        break;
                    case "--json":
                        jsonMode = true;
                        dataParts.Add(
                            ReadDataValue(
                                ReadValue(arguments, ref index, inlineValue, option, warnings),
                                warnings
                            )
                        );
                        AddHeaderIfMissing(headers, "Content-Type", "application/json");
                        AddHeaderIfMissing(headers, "Accept", "application/json");
                        break;
                    case "--get":
                        getMode = true;
                        break;
                    case "--head":
                        method = "HEAD";
                        break;
                    default:
                        if (IgnoredFlags.Contains(option))
                        {
                            break;
                        }

                        if (IgnoredValueOptions.Contains(option))
                        {
                            ReadValue(arguments, ref index, inlineValue, option, warnings);
                            warnings.Add($"cURL 参数 {option} 暂不支持，已忽略。");
                            break;
                        }

                        warnings.Add($"未识别的 cURL 参数 {option} 已忽略。");
                        break;
                }

                continue;
            }

            if (argument.StartsWith("-", StringComparison.Ordinal) && argument.Length > 1)
            {
                var option = argument[..2];
                var inlineValue = argument.Length > 2 ? argument[2..] : null;
                switch (option)
                {
                    case "-X":
                        method = ReadValue(arguments, ref index, inlineValue, option, warnings)
                            .Trim()
                            .ToUpperInvariant();
                        break;
                    case "-H":
                        AddHeader(
                            headers,
                            ReadValue(arguments, ref index, inlineValue, option, warnings),
                            warnings
                        );
                        break;
                    case "-d":
                        dataParts.Add(
                            ReadDataValue(
                                ReadValue(arguments, ref index, inlineValue, option, warnings),
                                warnings
                            )
                        );
                        break;
                    case "-F":
                        AddFormField(
                            ReadValue(arguments, ref index, inlineValue, option, warnings),
                            formFields,
                            warnings,
                            ref uploadFilePath,
                            ref uploadFieldName,
                            ref fileCount
                        );
                        break;
                    case "-u":
                        AddBasicAuth(
                            headers,
                            ReadValue(arguments, ref index, inlineValue, option, warnings),
                            warnings
                        );
                        break;
                    case "-A":
                        AddHeader(
                            headers,
                            $"User-Agent: {ReadValue(arguments, ref index, inlineValue, option, warnings)}",
                            warnings
                        );
                        break;
                    case "-e":
                        AddHeader(
                            headers,
                            $"Referer: {ReadValue(arguments, ref index, inlineValue, option, warnings)}",
                            warnings
                        );
                        break;
                    case "-b":
                        AddHeader(
                            headers,
                            $"Cookie: {ReadValue(arguments, ref index, inlineValue, option, warnings)}",
                            warnings
                        );
                        break;
                    case "-m":
                        timeoutSeconds = ParseTimeout(
                            ReadValue(arguments, ref index, inlineValue, option, warnings),
                            timeoutSeconds,
                            warnings
                        );
                        break;
                    case "-G":
                        getMode = true;
                        break;
                    case "-I":
                        method = "HEAD";
                        break;
                    default:
                        if (IgnoredFlags.Contains(option))
                        {
                            break;
                        }

                        if (IgnoredValueOptions.Contains(option))
                        {
                            ReadValue(arguments, ref index, inlineValue, option, warnings);
                            warnings.Add($"cURL 参数 {option} 暂不支持，已忽略。");
                            break;
                        }

                        warnings.Add($"未识别的 cURL 参数 {argument} 已忽略。");
                        break;
                }

                continue;
            }

            if (string.IsNullOrEmpty(url))
            {
                url = argument;
            }
            else
            {
                warnings.Add("cURL 命令包含多个 URL，MVP 只导入第一个。");
            }
        }

        if (string.IsNullOrWhiteSpace(url))
        {
            throw new InvalidOperationException(
                "cURL 命令没有请求 URL，请检查 -X/--url 或地址参数。"
            );
        }

        if (formFields.Count > 0 && dataParts.Count > 0)
        {
            warnings.Add("命令同时包含 -F 和 -d，已按 multipart 导入并忽略普通请求体。");
        }

        var body = string.Empty;
        var bodyMode = "None";
        if (formFields.Count > 0 || fileCount > 0)
        {
            bodyMode = "Multipart";
        }
        else if (dataParts.Count > 0)
        {
            if (getMode)
            {
                AddDataParameters(dataParts, parameters);
            }
            else
            {
                body = string.Join("&", dataParts);
                bodyMode =
                    jsonMode || HasJsonContentType(headers) || LooksLikeJson(body)
                        ? "Json"
                        : "Text";
                if (bodyMode == "Text")
                {
                    AddHeaderIfMissing(
                        headers,
                        "Content-Type",
                        "application/x-www-form-urlencoded"
                    );
                }
            }
        }

        if (string.IsNullOrEmpty(method))
        {
            method = bodyMode != "None" ? "POST" : "GET";
        }

        var request = new ImportedRequest
        {
            Name = BuildRequestName(url),
            Method = method,
            Url = url,
            BodyMode = bodyMode,
            Body = body,
            TimeoutSeconds = timeoutSeconds,
            UploadFilePath = uploadFilePath,
            UploadFieldName = uploadFieldName,
        };

        foreach (var parameter in parameters)
        {
            request.Params.Add(parameter);
        }

        foreach (var header in headers)
        {
            request.Headers.Add(new ImportedField(header.Key, header.Value));
        }

        foreach (var field in formFields)
        {
            request.FormFields.Add(field);
        }

        return new CurlImportResult { Request = request, Warnings = warnings.ToList() };
    }

    private static List<string> Tokenize(string command)
    {
        var tokens = new List<string>();
        var builder = new StringBuilder();
        var quote = '\0';
        var tokenStarted = false;

        for (var index = 0; index < command.Length; index++)
        {
            var character = command[index];
            if (quote == '\0' && character == '\\')
            {
                var continuationIndex = FindContinuation(command, index);
                if (continuationIndex >= 0)
                {
                    index = continuationIndex;
                    FlushToken(tokens, builder, ref tokenStarted);
                    continue;
                }

                if (index + 1 < command.Length && command[index + 1] is '\\' or '\'' or '"' or ' ')
                {
                    index++;
                    builder.Append(command[index]);
                    tokenStarted = true;
                    continue;
                }
            }

            if (quote == '\0' && character == '^')
            {
                var continuationIndex = FindContinuation(command, index);
                if (continuationIndex >= 0)
                {
                    index = continuationIndex;
                    FlushToken(tokens, builder, ref tokenStarted);
                    continue;
                }
            }

            if (quote != '\0')
            {
                if (character == quote)
                {
                    quote = '\0';
                }
                else
                {
                    builder.Append(character);
                }

                continue;
            }

            if (character is '\'' or '"')
            {
                quote = character;
                tokenStarted = true;
                continue;
            }

            if (char.IsWhiteSpace(character))
            {
                FlushToken(tokens, builder, ref tokenStarted);
                continue;
            }

            builder.Append(character);
            tokenStarted = true;
        }

        FlushToken(tokens, builder, ref tokenStarted);
        return tokens;
    }

    private static int FindContinuation(string value, int index)
    {
        if (index + 1 >= value.Length)
        {
            return -1;
        }

        if (value[index + 1] == '\n')
        {
            return index + 1;
        }

        if (value[index + 1] == '\r')
        {
            return index + 2 < value.Length && value[index + 2] == '\n' ? index + 2 : index + 1;
        }

        return -1;
    }

    private static void FlushToken(
        List<string> tokens,
        StringBuilder builder,
        ref bool tokenStarted
    )
    {
        if (!tokenStarted)
        {
            return;
        }

        tokens.Add(builder.ToString());
        builder.Clear();
        tokenStarted = false;
    }

    private static int FindCommandStart(IReadOnlyList<string> arguments)
    {
        for (var index = 0; index < arguments.Count; index++)
        {
            var name = Path.GetFileName(arguments[index]).ToLowerInvariant();
            if (name is "curl" or "curl.exe" or "curl.bat")
            {
                return index + 1;
            }
        }

        return -1;
    }

    private static (string Option, string? InlineValue) SplitLongOption(string argument)
    {
        var separator = argument.IndexOf('=');
        if (separator < 0)
        {
            return (argument, null);
        }

        return (argument[..separator], argument[(separator + 1)..]);
    }

    private static string ReadValue(
        IReadOnlyList<string> arguments,
        ref int index,
        string? inlineValue,
        string option,
        WarningBag warnings
    )
    {
        if (inlineValue is not null)
        {
            return inlineValue;
        }

        if (index + 1 >= arguments.Count)
        {
            warnings.Add($"cURL 参数 {option} 缺少值，已按空值处理。");
            return string.Empty;
        }

        index++;
        return arguments[index];
    }

    private static void SetUrl(ref string url, string value, WarningBag warnings)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            return;
        }

        if (string.IsNullOrEmpty(url))
        {
            url = value.Trim();
        }
        else if (!string.Equals(url, value.Trim(), StringComparison.Ordinal))
        {
            warnings.Add("cURL 命令包含多个 URL，MVP 只导入第一个。");
        }
    }

    private static void AddHeader(
        List<KeyValuePair<string, string>> headers,
        string raw,
        WarningBag warnings
    )
    {
        var separator = raw.IndexOf(':');
        if (separator <= 0)
        {
            warnings.Add($"无法识别请求头「{raw}」，已忽略。");
            return;
        }

        var key = raw[..separator].Trim();
        var value = raw[(separator + 1)..].TrimStart();
        if (string.IsNullOrEmpty(key))
        {
            warnings.Add($"请求头「{raw}」没有名称，已忽略。");
            return;
        }

        headers.Add(new KeyValuePair<string, string>(key, value));
    }

    private static void AddHeaderIfMissing(
        List<KeyValuePair<string, string>> headers,
        string key,
        string value
    )
    {
        if (headers.Any(header => header.Key.Equals(key, StringComparison.OrdinalIgnoreCase)))
        {
            return;
        }

        headers.Add(new KeyValuePair<string, string>(key, value));
    }

    private static void AddBasicAuth(
        List<KeyValuePair<string, string>> headers,
        string credentials,
        WarningBag warnings
    )
    {
        if (credentials.Contains("{{", StringComparison.Ordinal))
        {
            warnings.Add("Basic 认证包含变量，未自动转换；请在请求头中配置 Authorization。");
            return;
        }

        var encoded = Convert.ToBase64String(Encoding.UTF8.GetBytes(credentials));
        AddHeaderIfMissing(headers, "Authorization", $"Basic {encoded}");
    }

    private static void AddFormField(
        string raw,
        List<ImportedField> fields,
        WarningBag warnings,
        ref string uploadFilePath,
        ref string uploadFieldName,
        ref int fileCount
    )
    {
        var separator = raw.IndexOf('=');
        if (separator <= 0)
        {
            warnings.Add($"无法识别表单字段「{raw}」，已忽略。");
            return;
        }

        var key = raw[..separator].Trim();
        var value = raw[(separator + 1)..];
        if (value.StartsWith('@'))
        {
            fileCount++;
            var path = value[1..].Split(';', 2)[0].Trim();
            if (string.IsNullOrEmpty(path) || path == "-")
            {
                warnings.Add($"表单文件字段「{key}」没有可用的本地路径。");
                return;
            }

            if (fileCount == 1)
            {
                uploadFilePath = path;
                uploadFieldName = key;
            }
            else
            {
                warnings.Add("multipart 请求包含多个文件，MVP 只保留第一个文件。");
            }

            return;
        }

        if (value.StartsWith('<'))
        {
            warnings.Add($"表单字段「{key}」使用文件内容作为文本，已按原始值导入。");
        }

        fields.Add(new ImportedField(key, value));
    }

    private static void AddFormString(string raw, List<ImportedField> fields, WarningBag warnings)
    {
        var separator = raw.IndexOf('=');
        if (separator <= 0)
        {
            warnings.Add($"无法识别表单字段「{raw}」，已忽略。");
            return;
        }

        fields.Add(new ImportedField(raw[..separator].Trim(), raw[(separator + 1)..]));
    }

    private static string ReadDataValue(string value, WarningBag warnings)
    {
        if (!value.StartsWith('@'))
        {
            return value;
        }

        if (value == "@-")
        {
            warnings.Add("cURL 从标准输入读取请求体，PostSharp 无法导入 stdin，已跳过。");
            return string.Empty;
        }

        var path = value[1..];
        try
        {
            if (File.Exists(path))
            {
                return File.ReadAllText(path);
            }
        }
        catch (Exception exception)
        {
            Log.Warning(exception, "读取 cURL 请求体文件失败 {Path}", path);
            warnings.Add($"无法读取 cURL 请求体文件「{path}」，已按原值导入。");
            return value;
        }

        warnings.Add($"cURL 请求体文件「{path}」不存在，已按原值导入。");
        return value;
    }

    private static void AddDataParameters(
        IReadOnlyList<string> dataParts,
        List<ImportedField> parameters
    )
    {
        foreach (var part in dataParts)
        {
            foreach (var field in part.Split('&', StringSplitOptions.RemoveEmptyEntries))
            {
                var separator = field.IndexOf('=');
                var key = separator >= 0 ? field[..separator] : field;
                var value = separator >= 0 ? field[(separator + 1)..] : string.Empty;
                if (!string.IsNullOrEmpty(key))
                {
                    parameters.Add(new ImportedField(key, value));
                }
            }
        }
    }

    private static bool HasJsonContentType(IEnumerable<KeyValuePair<string, string>> headers)
    {
        return headers.Any(header =>
            header.Key.Equals("Content-Type", StringComparison.OrdinalIgnoreCase)
            && header.Value.Contains("json", StringComparison.OrdinalIgnoreCase)
        );
    }

    private static bool LooksLikeJson(string body)
    {
        var trimmed = body.TrimStart();
        return trimmed.StartsWith('{') || trimmed.StartsWith('[');
    }

    private static int ParseTimeout(string value, int current, WarningBag warnings)
    {
        if (
            double.TryParse(
                value,
                NumberStyles.Float,
                CultureInfo.InvariantCulture,
                out var seconds
            )
        )
        {
            return Math.Max(1, (int)Math.Ceiling(seconds));
        }

        warnings.Add($"无法识别 cURL 超时「{value}」，已使用全局超时。");
        return current;
    }

    private static string BuildRequestName(string url)
    {
        var withoutFragment = url.Split('#')[0];
        var withoutQuery = withoutFragment.Split('?')[0].TrimEnd('/');
        var slash = withoutQuery.LastIndexOf('/');
        var name = slash >= 0 ? withoutQuery[(slash + 1)..] : withoutQuery;
        if (string.IsNullOrWhiteSpace(name) || name.Contains("{{", StringComparison.Ordinal))
        {
            return "导入的 cURL 请求";
        }

        return name;
    }

    private sealed class WarningBag
    {
        private readonly List<string> _messages = new();
        private readonly HashSet<string> _seen = new(StringComparer.Ordinal);

        public void Add(string message)
        {
            if (_seen.Add(message))
            {
                _messages.Add(message);
            }
        }

        public IReadOnlyList<string> ToList() => _messages;
    }
}
